<script setup lang="ts">
const route = useRoute()
const router = useRouter()
const siteName = ref('Генетика Кроя')
const isAdmin = ref(false)

// Проверяем, авторизован ли пользователь как администратор
onMounted(async () => {
  try {
    const token = useCookie('admin-token')
    if (token.value) {
      const response = await $fetch('/api/admin/verify-token')
      isAdmin.value = !!response?.user
    }
  } catch (e) {
    isAdmin.value = false
  }
})

// Загрузка названия сайта
const { data: siteData } = await useFetch('/api/site-info')
if (siteData.value?.success) {
  siteName.value = siteData.value.siteName
}

const { data: course, pending, error } = await useFetch(
  `/api/courses/${route.params.slug}`
)

const { data: allCourses } = await useFetch('/api/courses')

const otherCourses = computed(() => {
  return allCourses.value?.courses?.filter(
    (c: any) => c.slug !== route.params.slug
  ) || []
})

const formatDescription = (text: string) => {
  if (!text) return ''
  return text
    .split('\n')
    .map(line => {
      if (line.startsWith('**') && line.endsWith('**')) {
        return `<strong>${line.replace(/\*\*/g, '')}</strong>`
      }
      if (line.startsWith('- ')) {
        return `<li>${line.substring(2)}</li>`
      }
      if (line.trim()) {
        return `<p>${line}</p>`
      }
      return ''
    })
    .join('')
}

useSeoMeta({
  title: () => `${course.value?.title} — {{ siteName }}`,
  description: () => course.value?.description,
})
</script>

